;(()=>{const u={"aplicativo":{"definition":"En informática, programa o conjunto de programas diseñado para que el usuario realice una tarea concreta; también se usa como adjetivo con el sentido de relativo a una aplicación. “Aplicativo” como sustantivo es más frecuente en algunas variedades de América.","synonyms":["aplicación informática","programa de aplicación","software de aplicación"],"example":{"word":"aplicativo","text":"El banco publicó un aplicativo móvil para consultar los movimientos de la cuenta."},"exampleSynonym":{"word":"aplicación informática","text":"El banco publicó una aplicación informática móvil para consultar los movimientos de la cuenta."},"translation":{"en":"application; application software; app"}},"arbitrable":{"definition":"Que puede someterse a arbitraje y resolverse por árbitros en lugar de un tribunal, conforme al acuerdo de las partes y a las materias que la ley permita someter a arbitraje.","synonyms":["susceptible de arbitraje","que puede resolverse mediante arbitraje"],"example":{"word":"arbitrable","text":"Las partes comprobaron si la controversia era arbitrable antes de iniciar el procedimiento."},"exampleSynonym":{"word":"susceptible de arbitraje","text":"Las partes comprobaron si la controversia era susceptible de arbitraje antes de iniciar el procedimiento."},"translation":{"en":"arbitrable; capable of being settled by arbitration"}},"asegurador":{"definition":"Como sustantivo, persona o entidad que asume contractualmente determinados riesgos a cambio de una prima; normalmente, una compañía de seguros. Como adjetivo, relativo al seguro o a quien lo ofrece.","synonyms":["compañía aseguradora (entidad)","entidad de seguros","relativo al seguro (adjetivo)"],"example":{"word":"asegurador","text":"El asegurador confirmó la cobertura prevista en la póliza."},"exampleSynonym":{"word":"compañía aseguradora","text":"La compañía aseguradora confirmó la cobertura prevista en la póliza."},"translation":{"en":"insurer; insurance company; insurance-related (adjective)"}},"asistencial":{"definition":"Perteneciente o relativo a la asistencia o atención prestada a personas, especialmente en los ámbitos sanitario y social.","synonyms":["de atención","relativo a los servicios de asistencia","de apoyo asistencial"],"example":{"word":"asistencial","text":"El centro asistencial ofrece atención sanitaria y social a personas mayores."},"exampleSynonym":{"word":"de atención","text":"El centro de atención ofrece atención sanitaria y social a personas mayores."},"translation":{"en":"care-providing; healthcare or social-care related"}},"autorizable":{"definition":"Que puede autorizarse si cumple las condiciones legales, administrativas o técnicas correspondientes; describe una posibilidad, no una autorización ya concedida.","synonyms":["susceptible de autorización","que puede recibir autorización"],"example":{"word":"autorizable","text":"La reforma solo será autorizable si respeta las normas de seguridad."},"exampleSynonym":{"word":"susceptible de autorización","text":"La reforma solo será susceptible de autorización si respeta las normas de seguridad."},"translation":{"en":"capable of being authorized; eligible for approval"}},"colaborativo":{"definition":"Que implica colaboración o se realiza con la participación coordinada de varias personas, grupos u organizaciones.","synonyms":["cooperativo","participativo","realizado en colaboración"],"example":{"word":"colaborativo","text":"El proyecto colaborativo reunió a docentes de tres centros."},"exampleSynonym":{"word":"cooperativo","text":"El proyecto cooperativo reunió a docentes de tres centros."},"translation":{"en":"collaborative; cooperative; joint"}},"contraseguro":{"definition":"Contrato o cláusula de seguro por el que la entidad aseguradora se compromete, si se cumplen determinadas condiciones, a devolver al asegurado las primas pagadas. No es un reaseguro que cubre los riesgos propios de la aseguradora.","synonyms":["seguro con devolución de primas","cláusula de reembolso de primas"],"example":{"word":"contraseguro","text":"La póliza incluye un contraseguro que prevé la devolución de las primas en ciertas circunstancias."},"exampleSynonym":{"word":"seguro con devolución de primas","text":"La póliza incluye un seguro con devolución de primas en ciertas circunstancias."},"translation":{"en":"return-of-premium insurance; premium-refund clause"}},"contratransferencia":{"definition":"En psicoterapia, especialmente en psicoanálisis, conjunto de reacciones, sentimientos, pensamientos y actitudes del terapeuta hacia el paciente y, en el sentido clásico, hacia la transferencia de este. El concepto y su alcance varían entre escuelas.","synonyms":["reacción del terapeuta hacia el paciente","respuesta contratransferencial"],"example":{"word":"contratransferencia","text":"La terapeuta examinó en supervisión su contratransferencia ante las reacciones del paciente."},"exampleSynonym":{"word":"reacción del terapeuta hacia el paciente","text":"La terapeuta examinó en supervisión su reacción hacia el paciente ante sus reacciones."},"translation":{"en":"countertransference"}},"cuasicontrato":{"definition":"En derecho civil, hecho lícito y voluntario que, sin basarse en un acuerdo contractual entre las partes, genera obligaciones reconocidas por la ley; su alcance y clasificación dependen de cada ordenamiento.","synonyms":["hecho lícito generador de obligaciones","fuente extracontractual de obligaciones (categoría civil)"],"example":{"word":"cuasicontrato","text":"El pago de una deuda ajena por error puede dar lugar a un cuasicontrato y a una obligación de restitución."},"exampleSynonym":{"word":"hecho lícito generador de obligaciones","text":"El pago de una deuda ajena por error puede ser un hecho lícito generador de obligaciones y dar lugar a una restitución."},"translation":{"en":"quasi-contract; non-contractual source of obligations in civil law"}},"deductibilidad":{"definition":"Cualidad de una cantidad, gasto o concepto que puede deducirse, especialmente al calcular una base imponible o un impuesto; depende de los requisitos legales aplicables. Variante de deducibilidad.","synonyms":["deducibilidad","carácter deducible","posibilidad de deducción fiscal"],"example":{"word":"deductibilidad","text":"La asesoría confirmó la deductibilidad fiscal del gasto conforme a la norma aplicable."},"exampleSynonym":{"word":"deducibilidad","text":"La asesoría confirmó la deducibilidad fiscal del gasto conforme a la norma aplicable."},"translation":{"en":"deductibility; tax-deductible status"}}};const rows=window.DICCIONARIOS.es;for(const [id,p]of Object.entries(u)){const row=rows.find(e=>e.id===id);if(!row)throw Error(id);Object.assign(row,p);}})();

