;(()=>{const u={"legalismo":{"definition":"Tendencia a aplicar la ley o sus procedimientos de manera rígida, atendiendo sobre todo a su letra o formalidades y dejando en segundo plano su finalidad o las circunstancias del caso.","synonyms":["formalismo jurídico excesivo","aplicación rígida de la ley","literalismo legal"],"example":{"word":"legalismo","text":"El legalismo llevó a rechazar la solicitud por un error formal que podía corregirse."},"exampleSynonym":{"word":"formalismo jurídico excesivo","text":"El formalismo jurídico excesivo llevó a rechazar la solicitud por un error formal que podía corregirse."},"translation":{"en":"legalism; excessive legal formalism; rigid application of the law"}},"licenciador":{"definition":"Persona, organismo o entidad que concede una licencia o autorización; en tecnología, titular que otorga a otra parte una licencia para usar una obra, programa o tecnología.","synonyms":["entidad que otorga licencias","organismo autorizante","licenciante (propiedad intelectual)"],"example":{"word":"licenciador","text":"El organismo licenciador verificó los requisitos antes de conceder el permiso."},"exampleSynonym":{"word":"organismo autorizante","text":"El organismo autorizante verificó los requisitos antes de conceder el permiso."},"translation":{"en":"licensor; licensing authority; licensing body"}},"medicamentar":{"definition":"Administrar o prescribir medicamentos a una persona o animal; la elección y dosis corresponden a un profesional sanitario cuando se trata de atención médica.","synonyms":["administrar medicación","tratar con medicamentos","medicar"],"example":{"word":"medicamentar","text":"El veterinario decidió medicamentar al animal tras examinarlo."},"exampleSynonym":{"word":"medicar","text":"El veterinario decidió medicar al animal tras examinarlo."},"translation":{"en":"medicate; treat with medication; administer medicine"}},"mediopensionado":{"definition":"Alumno de un centro educativo que recibe allí una o varias comidas, pero no reside en el establecimiento; también, relativo a ese régimen. Uso regional; en otros lugares se dice “medio pensionista”.","synonyms":["medio pensionista","alumno con servicio de comedor","estudiante no residente con comidas"],"example":{"word":"mediopensionado","text":"El alumno mediopensionado almuerza en el colegio y regresa a casa por la tarde."},"exampleSynonym":{"word":"medio pensionista","text":"El alumno medio pensionista almuerza en el colegio y regresa a casa por la tarde."},"translation":{"en":"day student who takes meals at school; non-resident student with meals"}},"pensionado":{"definition":"Persona que recibe una pensión, especialmente por jubilación, incapacidad o supervivencia; en algunos países, también alumno que reside o come en un centro educativo mediante pago.","synonyms":["pensionista","persona beneficiaria de una pensión","alumno interno o mediopensionista (regional, según el contexto)"],"example":{"word":"pensionado","text":"El pensionado recibió la prestación mensual en su cuenta bancaria."},"exampleSynonym":{"word":"pensionista","text":"El pensionista recibió la prestación mensual en su cuenta bancaria."},"translation":{"en":"pensioner; retiree; pension beneficiary; boarding student (regional sense)"}},"precontrato":{"definition":"Acuerdo previo por el que una o más partes se comprometen a celebrar un contrato posterior, o fijan las condiciones esenciales para hacerlo; sus efectos dependen del contenido y de la legislación aplicable.","synonyms":["contrato preliminar","acuerdo preparatorio","promesa de contrato (según el derecho aplicable)"],"example":{"word":"precontrato","text":"El precontrato fijó las condiciones que se incluirían en el contrato definitivo."},"exampleSynonym":{"word":"contrato preliminar","text":"El contrato preliminar fijó las condiciones que se incluirían en el contrato definitivo."},"translation":{"en":"preliminary contract; pre-contract; agreement to enter into a later contract"}},"prejubilar":{"definition":"Hacer que una persona se jubile antes de la edad ordinaria, normalmente mediante un acuerdo o medida laboral; también, acogerse a una jubilación anticipada en las condiciones previstas.","synonyms":["jubilar anticipadamente","anticipar la jubilación"],"example":{"word":"prejubilar","text":"La empresa acordó prejubilar a parte de su plantilla antes de la reestructuración."},"exampleSynonym":{"word":"jubilar anticipadamente","text":"La empresa acordó jubilar anticipadamente a parte de su plantilla antes de la reestructuración."},"translation":{"en":"offer early retirement; retire someone early; take early retirement (reflexive sense)"}},"regularizador":{"definition":"Que regulariza o pone algo en regla; como sustantivo, persona, entidad, procedimiento o mecanismo que normaliza una situación conforme a las normas.","synonyms":["normalizador","entidad que regulariza","organismo de regularización"],"example":{"word":"regularizador","text":"El programa regularizador permitió actualizar los permisos de residencia pendientes."},"exampleSynonym":{"word":"organismo de regularización","text":"El organismo de regularización permitió actualizar los permisos de residencia pendientes."},"translation":{"en":"regularizing; regularization authority or mechanism (context-dependent)"}},"adoptador":{"definition":"Adjetivo o sustantivo: que adopta; en derecho de familia, persona que recibe legalmente a otra como hijo. También puede referirse a quien adopta una idea, método o práctica. “Adoptante” es asimismo válido y más habitual en ciertos contextos.","synonyms":["adoptante","persona que adopta","receptor legal en una adopción"],"example":{"word":"adoptador","text":"El adoptador asumió las responsabilidades parentales previstas por la ley."},"exampleSynonym":{"word":"adoptante","text":"El adoptante asumió las responsabilidades parentales previstas por la ley."},"translation":{"en":"adopter; adoptive parent; person who adopts"}},"alegador":{"definition":"Adjetivo o sustantivo regional: persona que discute o disputa con frecuencia; en algunas zonas también se aplica a quien habla mucho o murmura. No significa necesariamente abogado ni persona que presenta argumentos jurídicos.","synonyms":["discutidor (regional)","amigo de disputas","hablador o murmurador (regional)"],"example":{"word":"alegador","text":"En esa región llaman alegador a quien discute por cualquier motivo."},"exampleSynonym":{"word":"discutidor","text":"En esa región llaman discutidor a quien discute por cualquier motivo."},"translation":{"en":"argumentative person; quarrelsome person; talkative person (regional senses)"}}};const rows=window.DICCIONARIOS.es;for(const [id,p]of Object.entries(u)){const row=rows.find(e=>e.id===id);if(!row)throw Error(id);Object.assign(row,p);}})();
