;(()=>{const u={"arcabuz":{"definition":"Arma de fuego portátil antigua, semejante a un fusil, que se disparaba mediante una mecha móvil que prendía la pólvora; también, arcabucero o soldado armado con ella (uso antiguo).","synonyms":["arma de mecha","arcabucero (sentido antiguo)"],"example":{"word":"arcabuz","text":"El arcabuz se disparaba acercando una mecha encendida a la pólvora."},"exampleSynonym":{"word":"arma de mecha","text":"El arma de mecha se disparaba acercando una mecha encendida a la pólvora."},"translation":{"en":"arquebus; matchlock firearm; arquebusier (archaic, second sense)"}},"arcabuzazo":{"definition":"Tiro disparado con un arcabuz; también, herida o daño causado por ese disparo.","synonyms":["tiro de arcabuz","disparo de arcabuz","herida de arcabuz (segundo sentido)"],"example":{"word":"arcabuzazo","text":"El cronista relató que el soldado recibió un arcabuzazo durante el asedio."},"exampleSynonym":{"word":"tiro de arcabuz","text":"El cronista relató que el soldado recibió un tiro de arcabuz durante el asedio."},"translation":{"en":"arquebus shot; wound caused by an arquebus shot"}},"arcada":{"definition":"Conjunto o serie de arcos, especialmente en un puente; también, el espacio entre dos pilas o estribos de un puente. En otra acepción, movimiento violento del estómago anterior o simultáneo al vómito.","synonyms":["arquería","ojo de un puente (sentido arquitectónico)","náusea","arqueada (sentido de vómito)"],"example":{"word":"arcada","text":"La arcada del puente tiene varios ojos; el olor provocó a uno de los visitantes una arcada."},"exampleSynonym":{"word":"arquería","text":"La arquería del puente tiene varios ojos; el olor provocó a uno de los visitantes una arcada."},"translation":{"en":"arcade; archway; bridge span; retching (by sense)"}},"arcaico":{"definition":"Muy antiguo o anticuado; en geología, dicho del eón más antiguo de la era precámbrica (Eón Arcaico).","synonyms":["antiguo","vetusto","anticuado","arcaico (geología: del Eón Arcaico)"],"example":{"word":"arcaico","text":"El museo conserva un arcaico instrumento; la roca se formó durante el Eón Arcaico."},"exampleSynonym":{"word":"vetusto","text":"El museo conserva un vetusto instrumento; la roca se formó durante el Eón Arcaico."},"translation":{"en":"archaic; ancient; outdated; Archean (geological sense)"}},"arcaizante":{"definition":"Que arcaíza, es decir, que emplea formas, palabras o estilos antiguos; también, que tiende a ser arcaico o anticuado.","synonyms":["arcaísta","anticuado","de estilo antiguo"],"example":{"word":"arcaizante","text":"La novela usa un lenguaje arcaizante para recrear la época."},"exampleSynonym":{"word":"de estilo antiguo","text":"La novela usa un lenguaje de estilo antiguo para recrear la época."},"translation":{"en":"archaizing; archaistic; tending to be archaic"}},"arcaizar":{"definition":"Usar palabras o modos antiguos en la expresión lingüística, el arte o las costumbres; también, dar a algo un carácter arcaico.","synonyms":["emplear arcaísmos","dar carácter antiguo","anticuar (según el contexto)"],"example":{"word":"arcaizar","text":"El autor decidió arcaizar el diálogo con vocabulario de otra época."},"exampleSynonym":{"word":"emplear arcaísmos","text":"El autor decidió emplear arcaísmos en el diálogo para evocar otra época."},"translation":{"en":"to archaize; to use archaic forms; to give an archaic quality"}},"arcangelico":{"definition":"Arcangélico: perteneciente o relativo a los arcángeles; también, angelical.","synonyms":["arcangelical","angelical"],"example":{"word":"arcangélico","text":"La pintura representa una figura arcangélica rodeada de luz."},"exampleSynonym":{"word":"angelical","text":"La pintura representa una figura angelical rodeada de luz."},"translation":{"en":"archangelic; angelic"}},"arcanidad":{"definition":"Poco usado. Secreto o carácter de aquello que es arcano.","synonyms":["secreto","misterio","enigma","incógnita"],"example":{"word":"arcanidad","text":"El tratado antiguo emplea «arcanidad» para referirse a un secreto."},"exampleSynonym":{"word":"secreto","text":"El tratado antiguo emplea «secreto» para referirse a una arcanidad."},"translation":{"en":"secrecy; mystery; arcane quality (rare)"}},"arcano":{"definition":"Secreto, recóndito o reservado; como sustantivo, secreto de gran importancia o misterio difícil de conocer.","synonyms":["secreto","oculto","recóndito","misterio","enigma"],"example":{"word":"arcano","text":"El manuscrito guardaba un arcano que pocos estudiosos lograron descifrar."},"exampleSynonym":{"word":"secreto","text":"El manuscrito guardaba un secreto que pocos estudiosos lograron descifrar."},"translation":{"en":"arcane; secret; mystery; enigma"}},"arcar":{"definition":"Dar forma de arco o arquear; en el trabajo tradicional de paños, sacudir y ahuecar la lana con un arco de una o dos cuerdas.","synonyms":["arquear","enarcar","ahuecar la lana (sentido textil)"],"example":{"word":"arcar","text":"El tejedor debía arcar la lana antes de hilarla."},"exampleSynonym":{"word":"ahuecar","text":"El tejedor debía ahuecar la lana antes de hilarla."},"translation":{"en":"to arch; to bow; to tease and fluff wool with a bow (textile craft)"}}};for(const[id,v]of Object.entries(u)){const e=DICCIONARIOS.es.find(x=>x.id===id);if(!e)throw Error('missing '+id);Object.assign(e,v)}})();

