"autobano":{definition:"m. Méx. Instalación para el lavado de automóviles; autolavado.",synonyms:["autolavado","lavado de autos"],example:{word:"autobaño",text:"Dejó el coche en un autobaño del barrio mientras hacía unas compras."},exampleSynonym:{word:"autolavado",text:"Dejó el coche en un autolavado del barrio mientras hacía unas compras."},translation:{en:"car wash (Mexico)"}},
