"autobomba":{definition:"f. Vehículo provisto de una bomba de agua para extinguir incendios; camión de bomberos con bomba.",synonyms:["carrobomba","camión autobomba","vehículo de bomberos con bomba"],example:{word:"autobomba",text:"Una autobomba llegó al lugar y comenzó a lanzar agua sobre las llamas."},exampleSynonym:{word:"camión autobomba",text:"Un camión autobomba llegó al lugar y comenzó a lanzar agua sobre las llamas."},translation:{en:"fire engine equipped with a water pump; pumper truck"}},
"autobombo":{definition:"m. fest. Elogio desmesurado y público que alguien hace de sí mismo o de sus propios méritos.",synonyms:["autoelogio","autopromoción","jactancia","vanagloria"],example:{word:"autobombo",text:"La entrevista se convirtió en un ejercicio de autobombo."},exampleSynonym:{word:"autoelogio",text:"La entrevista se convirtió en un ejercicio de autoelogio."},translation:{en:"self-praise; self-promotion; self-congratulation"}},
"autocar":{definition:"m. Autobús de gran capacidad destinado generalmente a viajes interurbanos o de larga distancia por carretera.",synonyms:["autobús de larga distancia","coach","ómnibus"],example:{word:"autocar",text:"El autocar salió de Madrid al anochecer y llegó a Lisboa por la mañana."},exampleSynonym:{word:"autobús de larga distancia",text:"El autobús de larga distancia salió de Madrid al anochecer y llegó a Lisboa por la mañana."},translation:{en:"coach; long-distance bus"}},
"autocensura":{definition:"f. Censura o limitación que una persona o entidad se impone a sí misma, a menudo para evitar críticas o represalias.",synonyms:["censura propia","restricción autoimpuesta","autorrestricción"],example:{word:"autocensura",text:"Por temor a represalias, el periodista recurrió a la autocensura."},exampleSynonym:{word:"censura propia",text:"Por temor a represalias, el periodista se impuso una censura propia."},translation:{en:"self-censorship; self-imposed restriction"}},
"bee":{definition:"noun: a flying insect of the superfamily Apoidea, many species of which pollinate plants. Also, a social gathering for a shared task or competition, such as a spelling bee; in idioms, a busy person.",synonyms:["honeybee (for honey-producing species)","spelling-bee insect (figurative use)"],example:{word:"bee",text:"A bee visited the flowers, and the children later joined a spelling bee."},exampleSynonym:{word:"honeybee",text:"A honeybee visited the flowers, and the children later joined a spelling competition."},translation:{es:"abeja; reunión colectiva para una tarea; concurso (como spelling bee); persona muy atareada en expresiones"}},
"busy-beaver":{definition:"noun, informal: a person who is very busy or industrious.",synonyms:["hard worker","busy bee","dynamo"],example:{word:"busy beaver",text:"She's been a busy beaver, finishing the report and organizing the files."},exampleSynonym:{word:"hard worker",text:"She's been a hard worker, finishing the report and organizing the files."},translation:{es:"persona muy trabajadora o atareada; trabajador incansable"}},
"busy-bee":{definition:"noun, informal: a person who is very busy or industrious; also used in the simile as busy as a bee.",synonyms:["busy-beaver","hard worker","industrious person"],example:{word:"busy bee",text:"Our busy bee finished the invitations before lunch."},exampleSynonym:{word:"hard worker",text:"Our hard worker finished the invitations before lunch."},translation:{es:"persona muy trabajadora o atareada; como una abeja laboriosa"}},
"bumblebee":{definition:"noun: a large, robust, hairy bee of the genus Bombus, known for its loud buzzing flight and role in pollination.",synonyms:["humblebee","Bombus bee"],example:{word:"bumblebee",text:"A bumblebee moved from flower to flower in the garden."},exampleSynonym:{word:"Bombus bee",text:"A Bombus bee moved from flower to flower in the garden."},translation:{es:"abejorro; abeja grande y peluda del género Bombus"}},
"hornet":{definition:"noun: a large social wasp, especially one of the genus Vespa, capable of delivering a painful sting.",synonyms:["Vespa wasp","large wasp"],example:{word:"hornet",text:"A hornet built a nest under the eaves."},exampleSynonym:{word:"large wasp",text:"A large wasp built a nest under the eaves."},translation:{es:"avispón; avispa grande del género Vespa"}},
"spruce":{definition:"noun: any evergreen conifer of the genus Picea, distinct from firs of the genus Abies. adjective: neat or smart in appearance. verb: to make neat or stylish.",synonyms:["Picea conifer","spruce tree"],example:{word:"spruce",text:"The spruce trees kept their needles through the winter."},exampleSynonym:{word:"Picea conifer",text:"The Picea conifers kept their needles through the winter."},translation:{es:"pícea; abeto rojo (género Picea); pulcro; arreglar o acicalar"}},
"fir":{definition:"noun: an evergreen conifer of the genus Abies, typically with upright cones and flat needles; distinct from spruces of the genus Picea.",synonyms:["Abies conifer","fir tree"],example:{word:"fir",text:"They decorated a fir tree for the winter holiday."},exampleSynonym:{word:"Abies conifer",text:"They decorated an Abies conifer for the winter holiday."},translation:{es:"abeto (género Abies)"}},
"ravine":{definition:"noun: a deep, narrow valley or gorge, often with steep sides and formed by erosion.",synonyms:["gorge","gully","defile"],example:{word:"ravine",text:"The hikers crossed the ravine at a narrow footbridge."},exampleSynonym:{word:"gorge",text:"The hikers crossed the gorge at a narrow footbridge."},translation:{es:"barranco; garganta; desfiladero estrecho"}},
"arroyo":{definition:"noun: a usually dry streambed or small channel that carries water after rain, especially in arid regions of the western United States.",synonyms:["dry creek","wash","gulch"],example:{word:"arroyo",text:"After the storm, water rushed through the normally dry arroyo."},exampleSynonym:{word:"dry creek",text:"After the storm, water rushed through the normally dry creek."},translation:{es:"arroyo; cauce normalmente seco que lleva agua tras las lluvias"}},
"abyss":{definition:"noun: an immeasurably deep or seemingly bottomless space, chasm, or gulf; figuratively, a profound difference or disastrous situation. In theology, the infernal pit or primeval chaos.",synonyms:["chasm","gulf","void","bottomless pit"],example:{word:"abyss",text:"The climbers peered into the abyss below the ridge."},exampleSynonym:{word:"chasm",text:"The climbers peered into the chasm below the ridge."},translation:{es:"abismo; sima; vacío; diferencia profunda; infierno (teología)"} }
