;(()=>{const u={"banzo":{"definition":"m. Cada uno de los largueros o listones que forman o refuerzan los lados de una armazón, como una escalera o un bastidor.","synonyms":["larguero","listón lateral","montante"],"example":{"word":"banzo","text":"El carpintero reforzó la escalera con un banzo nuevo."},"exampleSynonym":{"word":"larguero","text":"El carpintero reforzó la escalera con un larguero nuevo."},"translation":{"en":"side rail; stringer; frame rail"}},"banadera":{"word":"Bañadera","definition":"f. Arg., Bol., Par. y Ur. Bañera: recipiente grande para bañarse, especialmente una bañera exenta o de forma tradicional.","synonyms":["bañera","tina","baño"],"example":{"word":"bañadera","text":"Llenaron la bañadera con agua tibia para el niño."},"exampleSynonym":{"word":"bañera","text":"Llenaron la bañera con agua tibia para el niño."},"translation":{"en":"bathtub; bath (regional)"}},"banero":{"word":"Bañero","definition":"m. y f. Persona que cuida de los baños o atiende a quienes se bañan; en algunas regiones, socorrista de una playa o piscina.","synonyms":["encargado de baños","socorrista","guardavidas (regional)"],"example":{"word":"bañero","text":"El bañero preparó las toallas para los clientes del balneario."},"exampleSynonym":{"word":"encargado de baños","text":"El encargado de baños preparó las toallas para los clientes del balneario."},"translation":{"en":"bathing attendant; lifeguard (regional)"}},"baobab":{"definition":"m. Árbol de los trópicos del género Adansonia, de tronco muy grueso y ramas extendidas; es característico de África y Madagascar.","synonyms":["árbol botella","árbol del pan de mono"],"example":{"word":"baobab","text":"El baobab almacenaba agua en su enorme tronco durante la estación seca."},"exampleSynonym":{"word":"árbol botella","text":"El árbol botella almacenaba agua en su enorme tronco durante la estación seca."},"translation":{"en":"baobab; bottle tree"}},"baptismo":{"definition":"m. Forma antigua de bautismo; también, doctrina o práctica religiosa relativa al bautismo.","synonyms":["bautismo (forma moderna)","bautismo por inmersión (según el contexto)"],"example":{"word":"baptismo","text":"El documento antiguo describe el baptismo de los nuevos miembros de la comunidad."},"exampleSynonym":{"word":"bautismo","text":"El documento antiguo describe el bautismo de los nuevos miembros de la comunidad."},"translation":{"en":"baptism (archaic spelling); baptismal practice"}},"baptizar":{"definition":"tr. ant. Bautizar: administrar el sacramento del bautismo.","synonyms":["bautizar","administrar el bautismo"],"example":{"word":"baptizar","text":"El sacerdote decidió baptizar al niño en la capilla del pueblo."},"exampleSynonym":{"word":"bautizar","text":"El sacerdote decidió bautizar al niño en la capilla del pueblo."},"translation":{"en":"to baptize (archaic spelling)"}},"baque":{"definition":"m. Golpe que recibe una persona o cosa al caer; porrazo o batacazo.","synonyms":["golpe","porrazo","batacazo"],"example":{"word":"baque","text":"El baque de la caja contra el suelo hizo temblar la habitación."},"exampleSynonym":{"word":"golpe","text":"El golpe de la caja contra el suelo hizo temblar la habitación."},"translation":{"en":"thud; tumble; fall (regional)"}},"baqueano":{"definition":"m. y f. Am. Persona experta en los caminos y características de una región; guía conocedor del terreno.","synonyms":["baquiano","guía local","conocedor del terreno"],"example":{"word":"baqueano","text":"Contrataron a un baqueano para cruzar la sierra con seguridad."},"exampleSynonym":{"word":"guía local","text":"Contrataron a un guía local para cruzar la sierra con seguridad."},"translation":{"en":"local guide; guide familiar with the terrain (American regional)"}},"baqueta":{"definition":"f. Vara delgada para tocar instrumentos de percusión; también, varilla para limpiar o cargar el cañón de un arma de fuego.","synonyms":["palillo de tambor","varilla de limpieza","atacador"],"example":{"word":"baqueta","text":"La percusionista dejó caer una baqueta junto al tambor."},"exampleSynonym":{"word":"palillo de tambor","text":"La percusionista dejó caer un palillo de tambor junto al tambor."},"translation":{"en":"drumstick; ramrod"}},"baquetazo":{"definition":"m. Golpe dado con una baqueta.","synonyms":["golpe de baqueta","golpe","baquetazo"],"example":{"word":"baquetazo","text":"El percusionista dio un baquetazo al tambor para marcar el comienzo."},"exampleSynonym":{"word":"golpe de baqueta","text":"El percusionista dio un golpe de baqueta al tambor para marcar el comienzo."},"translation":{"en":"drumstick strike; blow with a rod"}}};for(const e of window.DICCIONARIOS.es)if(u[e.id])Object.assign(e,u[e.id]);})();
