set('cachanlagua',{definition:'Planta anual americana de la familia de las gencianáceas, semejante a la centaura menor y usada en medicina.',synonyms:['canchalagua','canchelagua'],example:{word:'cachanlagua',text:'La herbolaria local emplea la cachanlagua como planta medicinal.'},exampleSynonym:{word:'canchalagua',text:'La herbolaria local emplea la canchalagua como planta medicinal.'},translation:{en:'canchalagua (medicinal herb)'}});
