(()=>{for(const l of ['es','en'])if(DICCIONARIOS[l])for(const [id,x] of Object.entries({"es":{"cachear":{"definition":"Registrar a alguien palpándolo para saber si oculta objetos prohibidos.","synonyms":["registrar","examinar","inspeccionar","palpar"],"example":{"word":"cachear","text":"El agente tuvo que cachear al pasajero antes de entrar."},"exampleSynonym":{"word":"registrar","text":"El agente tuvo que registrar al pasajero antes de entrar."},"translation":{"en":"to frisk; to search by patting down"}},"cachemir":{"definition":"Adjetivo: perteneciente o relativo a la lengua cachemir. Como sustantivo masculino: tejido de pelo de cabra de Cachemira y lengua noroccidental del grupo indio hablada en esa región.","synonyms":["tejido de cachemir","casimir","lengua cachemir"],"example":{"word":"cachemir","text":"Compró una bufanda de cachemir muy suave."},"exampleSynonym":{"word":"tejido de cachemir","text":"Compró una bufanda de tejido de cachemir muy suave."},"translation":{"en":"cashmere; Kashmiri; the Kashmiri language"}},"cachera":{"definition":"Antiguamente, ropa de lana muy tosca y de pelo largo.","synonyms":["ropa basta de lana","vestimenta de lana tosca"],"example":{"word":"cachera","text":"El pastor llevaba una cachera de lana basta para protegerse del frío."},"exampleSynonym":{"word":"ropa basta de lana","text":"El pastor llevaba ropa basta de lana para protegerse del frío."},"translation":{"en":"coarse long-pile wool clothing (archaic)"}},"cachetear":{"definition":"En Andalucía y América, golpear a alguien en la cara con la mano abierta; coloquialmente, en Puerto Rico, obtener algo gratis o a costa de otra persona.","synonyms":["abofetear","dar una bofetada","obtener de gorra"],"example":{"word":"cachetear","text":"En la escena, el actor fingió cachetear al villano."},"exampleSynonym":{"word":"abofetear","text":"En la escena, el actor fingió abofetear al villano."},"translation":{"en":"to slap; to get something for free (Puerto Rico)"}},"cachicamo":{"definition":"En Ecuador, Perú y Venezuela, armadillo: mamífero americano con el cuerpo cubierto de placas córneas articuladas.","synonyms":["armadillo","cusuco","tatú"],"example":{"word":"cachicamo","text":"Vieron un cachicamo cruzar lentamente el camino."},"exampleSynonym":{"word":"armadillo","text":"Vieron un armadillo cruzar lentamente el camino."},"translation":{"en":"armadillo"}},"cachilo":{"definition":"En Uruguay, automóvil viejo; también, en sentido afectivo, automóvil propio, generalmente modesto.","synonyms":["cachila","auto viejo","automóvil modesto"],"example":{"word":"cachilo","text":"A pesar de sus años, el cachilo los llevaba a todas partes."},"exampleSynonym":{"word":"cachila","text":"A pesar de sus años, el auto viejo los llevaba a todas partes."},"translation":{"en":"old car; modest personal car"}},"cachimba":{"definition":"Pipa para fumar; en Argentina y Uruguay, hoyo para buscar agua; en El Salvador, semblante adusto o calabaza alargada; en México, cabo o resto de un puro.","synonyms":["pipa","cacimba","semblante adusto","resto de un puro"],"example":{"word":"cachimba","text":"Encendió la cachimba y se sentó junto a la ventana."},"exampleSynonym":{"word":"pipa","text":"Encendió la pipa y se sentó junto a la ventana."},"translation":{"en":"smoking pipe; water hole; stern expression; cigar stub"}},"cachimbear":{"definition":"En El Salvador y Honduras, golpear a alguien; en Chile, molestar o importunar repetidamente; en El Salvador y Honduras, dicho de una persona, trabajar duramente.","synonyms":["golpear","importunar","trabajar duramente"],"example":{"word":"cachimbear","text":"Dejó de cachimbear a su hermano con las mismas bromas."},"exampleSynonym":{"word":"importunar","text":"Dejó de importunar a su hermano con las mismas bromas."},"translation":{"en":"to beat; to pester; to work hard"}},"cachimbo":{"definition":"En varios países, pipa para fumar; en Colombia, bucare; en El Salvador, Guatemala, Honduras y Nicaragua, gran cantidad de cosas; en Perú, músico de banda o estudiante de primer año de educación superior.","synonyms":["pipa","bucare","gran cantidad","músico de banda","estudiante de primer año"],"example":{"word":"cachimbo","text":"El estudiante recién ingresado era todavía un cachimbo en la universidad."},"exampleSynonym":{"word":"estudiante de primer año","text":"El estudiante recién ingresado era todavía un estudiante de primer año en la universidad."},"translation":{"en":"smoking pipe; bucare tree; large quantity; band musician; first-year university student"}},"cachina":{"definition":"En Perú, licor barato y dulce hecho de mosto ligeramente fermentado.","synonyms":["licor de mosto","vino dulce joven"],"example":{"word":"cachina","text":"En la feria probaron una cachina dulce hecha con mosto."},"exampleSynonym":{"word":"licor de mosto","text":"En la feria probaron un licor de mosto dulce."},"translation":{"en":"cachina (Peruvian lightly fermented grape must)"}}},"en":{"disaster":{"definition":"A sudden event that causes great damage, loss, or destruction; also, a complete failure, a very bad result, or a person or place in a severely disordered state.","synonyms":["catastrophe","calamity","fiasco","mess"],"example":{"word":"disaster","text":"The flood was a disaster for the small coastal town."},"exampleSynonym":{"word":"catastrophe","text":"The flood was a catastrophe for the small coastal town."},"translation":{"es":"desastre; catástrofe; fracaso"}},"untied":{"definition":"Not tied or fastened; loosened or undone.","synonyms":["unfastened","loose","undone"],"example":{"word":"untied","text":"His untied shoelaces dragged along the pavement."},"exampleSynonym":{"word":"unfastened","text":"His unfastened shoelaces dragged along the pavement."},"translation":{"es":"desatado; suelto; desabrochado"}},"barefoot":{"definition":"With the feet bare, without shoes or other footwear; used as an adjective or adverb.","synonyms":["unshod","barefooted"],"example":{"word":"barefoot","text":"The children ran barefoot across the grass."},"exampleSynonym":{"word":"unshod","text":"The children ran unshod across the grass."},"translation":{"es":"descalzo; a pie descalzo"}},"unshod":{"definition":"Not wearing or provided with shoes; especially, a horse without shoes.","synonyms":["barefoot","shoeless"],"example":{"word":"unshod","text":"The unshod horse walked carefully over the stones."},"exampleSynonym":{"word":"barefoot","text":"The barefoot horse walked carefully over the stones."},"translation":{"es":"descalzo; sin herraduras"}},"distrust":{"definition":"Noun: lack or absence of trust or confidence. Verb: to have no trust or confidence in someone or something.","synonyms":["mistrust","suspicion","doubt","skepticism"],"example":{"word":"distrust","text":"Years of broken promises created distrust between the neighbors."},"exampleSynonym":{"word":"mistrust","text":"Years of broken promises created mistrust between the neighbors."},"translation":{"es":"desconfianza; desconfiar"}},"defrost":{"definition":"To free something from frost or ice; to thaw food or another frozen substance, or to clear frost from a refrigerator window or vehicle windshield.","synonyms":["thaw","deice","unfreeze"],"example":{"word":"defrost","text":"Remember to defrost the bread before dinner."},"exampleSynonym":{"word":"thaw","text":"Remember to thaw the bread before dinner."},"translation":{"es":"descongelar; quitar el hielo"}},"unknown":{"definition":"Adjective: not known, not well known, or having an undetermined value. Noun: a person or thing not known, an unexplored situation, an undiscovered fact, or a mathematical variable.","synonyms":["unidentified","unfamiliar","obscure"],"example":{"word":"unknown","text":"An unknown caller left a message on her phone."},"exampleSynonym":{"word":"unidentified","text":"An unidentified caller left a message on her phone."},"translation":{"es":"desconocido; no identificado; incógnita"}},"stranger":{"definition":"Noun: a person one does not know, a visitor or newcomer, or someone unfamiliar with a place or subject. Adjective: relating to a stranger or foreign. Also the comparative form of strange.","synonyms":["newcomer","visitor","outsider"],"example":{"word":"stranger","text":"A stranger asked for directions outside the station."},"exampleSynonym":{"word":"newcomer","text":"A newcomer asked for directions outside the station."},"translation":{"es":"desconocido; forastero; más extraño"}},"impolite":{"definition":"Not polite; lacking good manners or consideration for others.","synonyms":["rude","discourteous","uncivil"],"example":{"word":"impolite","text":"Interrupting someone repeatedly is impolite."},"exampleSynonym":{"word":"discourteous","text":"Interrupting someone repeatedly is discourteous."},"translation":{"es":"descortés; maleducado"}},"describe":{"definition":"To represent or give an account of someone or something in words; to depict with a figure or picture; or to trace the outline of a shape.","synonyms":["depict","portray","characterize","outline"],"example":{"word":"describe","text":"Please describe the person you saw near the gate."},"exampleSynonym":{"word":"depict","text":"Please depict the person you saw near the gate."},"translation":{"es":"describir; representar; trazar"}}}}[l]))(()=>{const e=DICCIONARIOS[l].find(e=>e.id===id);if(e)Object.assign(e,x)})();})();

